auto leaveRoomLambda = [](NeoChatRoom *room, const QString &text, const QString &, const QString &) {
    if (text.isEmpty()) {
        Q_EMIT room->showMessage(MessageType::Information, i18n("Leaving this room."));
        room->forget();
    } else {
        // FIXME: re-add sanity check for roomId/alias
        auto leaving = dynamic_cast<NeoChatRoom *>(room->connection()->room(text));
        if (!leaving) {
            leaving = dynamic_cast<NeoChatRoom *>(room->connection()->roomByAlias(text));
        }
        if (leaving) {
            Q_EMIT room->showMessage(MessageType::Information, i18nc("Leaving room <roomname>.", "Leaving room %1.", text));
            leaving->forget();
        } else {
            Q_EMIT room->showMessage(MessageType::Information, i18nc("Room <roomname> not found", "Room %1 not found.", text));
        }
    }
    return QString();
};

auto roomNickLambda = [](NeoChatRoom *room, const QString &text, const QString &, const QString &) {
    if (text.isEmpty()) {
        Q_EMIT room->showMessage(MessageType::Error, i18n("No new nickname provided, no changes will happen."));
    } else {
        room->connection()->user()->rename(text, room);
    }
    return QString();
};

